import { addBook } from "./store.mjs";

const esc = (v) => {
  const s = String(v);
  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

export function exportBooks(store) {
  const lines = ["id,title,author,year,tags,copies"];
  for (const b of store.books) lines.push([b.id, b.title, b.author, b.year, b.tags.join(";"), b.copies].map(esc).join(","));
  return lines.join("\n") + "\n";
}

// Returns records as { line, fields }.
function parse(text) {
  const records = [];
  let fields = [], cur = "", quoted = false, line = 1, start = 1, any = false;
  const endRecord = () => {
    fields.push(cur);
    if (any || fields.length > 1 || fields[0] !== "") records.push({ line: start, fields });
    fields = []; cur = ""; any = false;
  };
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quoted) {
      if (c === '"') {
        if (text[i + 1] === '"') { cur += '"'; i++; } else quoted = false;
      } else { if (c === "\n") line++; cur += c; }
    } else if (c === '"') { quoted = true; any = true; }
    else if (c === ",") { fields.push(cur); cur = ""; any = true; }
    else if (c === "\n" || c === "\r") {
      if (c === "\r" && text[i + 1] === "\n") i++;
      endRecord(); line++; start = line;
    } else { cur += c; any = true; }
  }
  if (cur !== "" || any || fields.length) endRecord();
  return records;
}

export function importBooks(store, text) {
  const recs = parse(text);
  const errors = [];
  let added = 0;
  if (!recs.length) return { added, errors };
  const cols = recs[0].fields.map((c) => c.trim());
  for (const { line, fields } of recs.slice(1)) {
    const row = {};
    cols.forEach((c, i) => (row[c] = fields[i] ?? ""));
    const title = (row.title ?? "").trim(), author = (row.author ?? "").trim();
    const year = (row.year ?? "").trim(), copiesS = (row.copies ?? "").trim();
    let message = null;
    if (!title) message = "title is required";
    else if (!author) message = "author is required";
    else if (!/^-?\d+$/.test(year)) message = "year must be a whole number";
    else if (copiesS !== "" && !/^\d+$/.test(copiesS)) message = "copies must be a positive whole number";
    else if (copiesS !== "" && Number(copiesS) < 1) message = "copies must be a positive whole number";
    if (message) { errors.push({ line, message }); continue; }
    const tags = (row.tags ?? "").split(";").map((t) => t.trim()).filter(Boolean);
    addBook(store, { title, author, year: Number(year), tags, copies: copiesS === "" ? 1 : Number(copiesS) });
    added++;
  }
  return { added, errors };
}
