import { createServer as httpServer } from "node:http";
import { getBook, checkout } from "./store.mjs";
import { search } from "./search.mjs";
import { memberBalance } from "./fines.mjs";

export function createServer(store) {
  return httpServer(async (req, res) => {
    const send = (status, body) => {
      res.writeHead(status, { "Content-Type": "application/json" });
      res.end(JSON.stringify(body));
    };
    const notFound = () => send(404, { error: "not found" });
    try {
      const url = new URL(req.url, "http://localhost");
      const parts = url.pathname.split("/").filter(Boolean).map(decodeURIComponent);
      const p = url.searchParams;
      if (req.method === "GET" && parts[0] === "books" && parts.length === 1) {
        const query = {};
        for (const k of ["q", "author", "tag"]) if (p.has(k)) query[k] = p.get(k);
        for (const k of ["page", "pageSize"]) if (p.has(k)) query[k] = Number(p.get(k));
        return send(200, search(store, query));
      }
      if (req.method === "GET" && parts[0] === "books" && parts.length === 2) {
        const book = getBook(store, parts[1]);
        return book ? send(200, book) : notFound();
      }
      if (req.method === "POST" && parts[0] === "loans" && parts.length === 1) {
        let raw = "";
        for await (const chunk of req) raw += chunk;
        let body;
        try { body = JSON.parse(raw || "{}"); } catch { return send(400, { error: "invalid json" }); }
        for (const f of ["bookId", "memberId", "date"]) {
          if (body?.[f] === undefined || body[f] === null || body[f] === "") return send(400, { error: `missing ${f}` });
        }
        try {
          return send(201, checkout(store, body.bookId, body.memberId, body.date));
        } catch (e) {
          return send(409, { error: e.message });
        }
      }
      if (req.method === "GET" && parts[0] === "members" && parts[2] === "balance" && parts.length === 3) {
        return send(200, { memberId: parts[1], balance: memberBalance(store, parts[1], p.get("asOf")) });
      }
      return notFound();
    } catch (e) {
      send(500, { error: e.message });
    }
  });
}
