import { addBook } from "./store.mjs";

const quote = (v) => {
  const s = String(v);
  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

export function exportBooks(store) {
  const lines = ["id,title,author,year,tags,copies"];
  for (const b of store.books) {
    lines.push([b.id, b.title, b.author, b.year, b.tags.join(";"), b.copies].map(quote).join(","));
  }
  return lines.join("\n") + "\n";
}

// Returns [{ line, fields }]; line is the 1-based line where the record starts.
function parse(text) {
  const records = [];
  let fields = [];
  let field = "";
  let inQuotes = false;
  let line = 1;
  let start = 1;
  let pending = false;
  const endRecord = () => {
    fields.push(field);
    if (!(fields.length === 1 && fields[0] === "" && !pending)) records.push({ line: start, fields });
    fields = [];
    field = "";
    pending = false;
  };
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; } else inQuotes = false;
      } else {
        if (c === "\n") line++;
        field += c;
      }
    } else if (c === '"') {
      inQuotes = true;
      pending = true;
    } else if (c === ",") {
      fields.push(field);
      field = "";
      pending = true;
    } else if (c === "\r" && text[i + 1] === "\n") {
      // handled by the following \n
    } else if (c === "\n") {
      endRecord();
      line++;
      start = line;
    } else {
      field += c;
    }
  }
  if (field !== "" || fields.length || pending) endRecord();
  return records;
}

const WHOLE = /^-?\d+$/;

export function importBooks(store, text) {
  const records = parse(text);
  const errors = [];
  let added = 0;
  if (!records.length) return { added, errors };
  const header = records[0].fields.map((h) => h.trim());
  const col = (name) => header.indexOf(name);
  for (const { line, fields } of records.slice(1)) {
    const get = (name) => (col(name) < 0 ? "" : (fields[col(name)] ?? ""));
    const title = get("title").trim();
    const author = get("author").trim();
    const yearStr = get("year").trim();
    const copiesStr = get("copies").trim();
    const fail = (message) => errors.push({ line, message });
    if (!title) { fail("title is required"); continue; }
    if (!author) { fail("author is required"); continue; }
    if (!WHOLE.test(yearStr)) { fail("year must be a whole number"); continue; }
    let copies = 1;
    if (copiesStr !== "") {
      if (!/^\d+$/.test(copiesStr) || Number(copiesStr) < 1) { fail("copies must be a positive whole number"); continue; }
      copies = Number(copiesStr);
    }
    const tagStr = get("tags").trim();
    const tags = tagStr === "" ? [] : tagStr.split(";");
    addBook(store, { title, author, year: Number(yearStr), tags, copies });
    added++;
  }
  return { added, errors };
}
