import { daysBetween } from "./dates.mjs";

const GRACE_DAYS = 2;
const RATE = 0.25;
const CAP = 10;

const cents = (n) => Math.round(n * 100) / 100;

export function finesFor(store, memberId, asOf) {
  const fines = [];
  for (const loan of store.loans) {
    if (loan.memberId !== memberId) continue;
    const daysLate = daysBetween(loan.due, loan.returned ?? asOf) - GRACE_DAYS;
    if (daysLate <= 0) continue;
    fines.push({ loanId: loan.id, bookId: loan.bookId, daysLate, amount: cents(Math.min(daysLate * RATE, CAP)) });
  }
  return fines.sort((a, b) => (a.loanId < b.loanId ? -1 : a.loanId > b.loanId ? 1 : 0));
}

export function memberBalance(store, memberId, asOf) {
  const fined = finesFor(store, memberId, asOf).reduce((s, f) => s + f.amount, 0);
  const paid = store.payments.filter((p) => p.memberId === memberId).reduce((s, p) => s + p.amount, 0);
  return cents(fined - paid);
}

export function payFine(store, memberId, amount, date) {
  store.payments.push({ memberId, amount, date });
  return memberBalance(store, memberId, date);
}
