// CSV export/import of books.
import { addBook } from "./store.mjs";

const COLUMNS = ["id", "title", "author", "year", "tags", "copies"];

const quote = (v) => {
  const s = String(v ?? "");
  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

export function exportBooks(store) {
  const lines = [COLUMNS.join(",")];
  for (const b of store.books) {
    lines.push([b.id, b.title, b.author, b.year, b.tags.join(";"), b.copies].map(quote).join(","));
  }
  return lines.join("\n") + "\n";
}

// Returns [{ line, fields }] where line is the 1-based line the record starts on.
function parseRecords(text) {
  const records = [];
  let fields = [];
  let field = "";
  let inQuotes = false;
  let line = 1;
  let start = 1;
  let any = false;
  const endRecord = () => {
    fields.push(field);
    records.push({ line: start, fields, blank: !any });
    fields = [];
    field = "";
    any = false;
  };
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; } else inQuotes = false;
      } else {
        if (c === "\n") line++;
        field += c;
      }
    } else if (c === '"') {
      inQuotes = true;
      any = true;
    } else if (c === ",") {
      fields.push(field);
      field = "";
      any = true;
    } else if (c === "\n" || c === "\r") {
      if (c === "\r" && text[i + 1] === "\n") i++;
      endRecord();
      line++;
      start = line;
    } else {
      field += c;
      any = true;
    }
  }
  if (any || field !== "" || fields.length) endRecord();
  return records;
}

const WHOLE = /^-?\d+$/;

export function importBooks(store, text) {
  const records = parseRecords(text).filter((r, i) => i === 0 || !r.blank);
  const errors = [];
  let added = 0;
  if (!records.length) return { added, errors };
  const header = records[0].fields.map((h) => h.trim());
  const col = (name) => header.indexOf(name);
  for (const name of ["title", "author", "year", "tags", "copies"]) {
    if (col(name) < 0) {
      errors.push({ line: 1, message: `missing column: ${name}` });
    }
  }
  if (errors.length) return { added, errors };
  for (const { line, fields } of records.slice(1)) {
    const get = (name) => (fields[col(name)] ?? "").trim();
    const title = get("title");
    const author = get("author");
    const yearText = get("year");
    const copiesText = get("copies");
    const err = (message) => errors.push({ line, message });
    if (!title) err("title is required");
    else if (!author) err("author is required");
    else if (!WHOLE.test(yearText)) err("year must be a whole number");
    else if (copiesText !== "" && !(WHOLE.test(copiesText) && Number(copiesText) > 0)) {
      err("copies must be a positive whole number");
    } else {
      const tagsText = get("tags");
      addBook(store, {
        title,
        author,
        year: Number(yearText),
        tags: tagsText ? tagsText.split(";") : [],
        copies: copiesText === "" ? 1 : Number(copiesText),
      });
      added++;
    }
  }
  return { added, errors };
}
