// HTTP API over the library store. JSON in and out.
import { createServer as httpServer } from "node:http";
import { checkout, getBook } from "./store.mjs";
import { search } from "./search.mjs";
import { memberBalance } from "./fines.mjs";

const NOT_FOUND = { error: "not found" };

function send(res, status, body) {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(body));
}

function readJson(req) {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk) => (data += chunk));
    req.on("end", () => {
      try {
        resolve(data ? JSON.parse(data) : {});
      } catch {
        reject(new Error("invalid json"));
      }
    });
    req.on("error", reject);
  });
}

async function handle(store, req, res) {
  const url = new URL(req.url, "http://localhost");
  const parts = url.pathname.split("/").filter(Boolean).map(decodeURIComponent);
  const q = url.searchParams;

  if (req.method === "GET" && parts.length === 1 && parts[0] === "books") {
    const query = {};
    for (const key of ["q", "author", "tag"]) if (q.has(key)) query[key] = q.get(key);
    for (const key of ["page", "pageSize"]) if (q.has(key)) query[key] = Number(q.get(key));
    return send(res, 200, search(store, query));
  }
  if (req.method === "GET" && parts.length === 2 && parts[0] === "books") {
    const book = getBook(store, parts[1]);
    return book ? send(res, 200, book) : send(res, 404, NOT_FOUND);
  }
  if (req.method === "POST" && parts.length === 1 && parts[0] === "loans") {
    let body;
    try {
      body = await readJson(req);
    } catch (err) {
      return send(res, 400, { error: err.message });
    }
    for (const field of ["bookId", "memberId", "date"]) {
      if (body?.[field] === undefined || body[field] === null || body[field] === "") {
        return send(res, 400, { error: `missing ${field}` });
      }
    }
    try {
      return send(res, 201, checkout(store, body.bookId, body.memberId, body.date));
    } catch (err) {
      return send(res, 409, { error: err.message });
    }
  }
  if (req.method === "GET" && parts.length === 3 && parts[0] === "members" && parts[2] === "balance") {
    const asOf = q.get("asOf") ?? new Date().toISOString().slice(0, 10);
    return send(res, 200, { memberId: parts[1], balance: memberBalance(store, parts[1], asOf) });
  }
  return send(res, 404, NOT_FOUND);
}

export function createServer(store) {
  return httpServer((req, res) => {
    handle(store, req, res).catch((err) => {
      if (!res.headersSent) send(res, 500, { error: err.message });
      else res.end();
    });
  });
}
